import React, { useCallback, useEffect, useMemo, useState } from 'react';
import { Button, IntegerInput, Modal, MoneyInput, SearchInput, Slideout, dispatchAppToast } from '@linm-soft-org/linm-web-common-components';
import { formatAccountDisplay } from '../search/accountSearchApi';
import {
  createCompanyCodeSearchConfig,
  createCostCodeSearchConfig,
  type CompanyCodeLookupItem,
  type CostCodeLookupItem,
} from '../../pages/kt/ImportSaoKePage/components/StepClassifyImp/createClassifyLookupConfigs';
import { useAppDispatch } from '../../store/hooks';
import { apiClient, unwrap, type BffResponse } from '../../services/api';
import type {
  CashVoucherCompanyAllocationDto,
  CompanyAllocationMethod,
  CompanyAllocationScope,
  SaveCashVoucherCompanyAllocationDto,
} from '../../services/kt/models';
import { formatMoneyVnd } from '../../utils/formatters';
import { getApiErrorMessage } from '../../utils/getApiErrorMessage';
import formStyles from '../../styles/documentForm.module.css';
import styles from './CompanyAllocateSlideout.module.css';

export type CompanyAllocateConfirmPayload = SaveCashVoucherCompanyAllocationDto;

export type VoucherLineOption = {
  id: string;
  label: string;
  amount: number;
  costCode?: string;
  costCodeName?: string;
  rowOrderKey?: number;
};

export type CompanyAllocateSlideoutProps = {
  isOpen: boolean;
  onClose: () => void;
  voucherTotal: number;
  /** Dòng CT (multi-line → cho chọn Common|ByLine). */
  voucherLines?: VoucherLineOption[];
  initialMethod?: CompanyAllocationMethod | string;
  initialScope?: CompanyAllocationScope | string;
  /** Mở từ nút dòng — ByLine + chọn hạng mục này. */
  initialActiveLineId?: string | null;
  initialLines?: CashVoucherCompanyAllocationDto[];
  onConfirm: (payload: CompanyAllocateConfirmPayload) => void | Promise<void>;
  /** Khi ByLine + confirm — mở tab chi tiết hạng mục (optional shell). */
  onOpenLineDetailTab?: (payload: CompanyAllocateConfirmPayload) => void;
  testIdPrefix: string;
  saving?: boolean;
  readOnly?: boolean;
};

type CompanyRow = {
  rowKey: string;
  code: string;
  name: string;
  costCode: string;
  costCodeName: string;
  selected: boolean;
  amount: number;
  ratio: number;
  /** CL làm tròn trên dòng — cho phép ± */
  cl: number;
};

function newRowKey(): string {
  return `r-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`;
}

/** Buffer 1 hạng mục (ByLine) — method per line. */
type LineBucket = {
  rows: CompanyRow[];
  method: CompanyAllocationMethod;
  clAmount: number;
  clCode: string;
};

type ActiveCompanyApiItem = {
  id: string;
  code?: string;
  name: string;
  shortName?: string;
};

const METHOD_OPTIONS: { value: CompanyAllocationMethod; label: string }[] = [
  { value: 'Manual', label: 'Đích danh' },
  { value: 'Equal', label: 'Phân bổ bình quân' },
  { value: 'Ratio', label: 'Phân bổ tỷ lệ' },
];

const SYSTEM_CODES = new Set(['SYSTEM']);

function lineCostCode(line: unknown): string {
  if (!line || typeof line !== 'object') return '';
  const cost = (line as Record<string, unknown>).costCode;
  return typeof cost === 'string' ? cost.trim() : '';
}

function methodLabel(m: CompanyAllocationMethod): string {
  return METHOD_OPTIONS.find(o => o.value === m)?.label ?? m;
}

function normalizeMethod(raw: string | undefined | null): CompanyAllocationMethod {
  const m = (raw ?? '').trim();
  if (m === 'Manual' || m.toLowerCase() === 'manual') return 'Manual';
  if (m === 'Ratio' || m.toLowerCase() === 'ratio') return 'Ratio';
  if (m === 'Equal' || m.toLowerCase() === 'equal') return 'Equal';
  return 'Manual';
}

function normalizeScope(raw: string | undefined | null): CompanyAllocationScope {
  const s = (raw ?? '').trim();
  if (s.toLowerCase() === 'byline' || s === 'ByLine') return 'ByLine';
  return 'Common';
}

function round0(n: number): number {
  return Math.round(n);
}

function isSystemCode(code: string): boolean {
  return SYSTEM_CODES.has(code.trim().toUpperCase());
}

async function fetchActiveCompanies(): Promise<{ code: string; name: string }[]> {
  const byCode = new Map<string, { code: string; name: string }>();
  try {
    const res = await apiClient.get<BffResponse<ActiveCompanyApiItem[]>>('/companies/active-list');
    for (const item of unwrap(res) ?? []) {
      const code = (item.code || item.id || '').trim();
      if (!code || isSystemCode(code)) continue;
      byCode.set(code.toUpperCase(), {
        code,
        name: (item.name || item.shortName || code).trim(),
      });
    }
  } catch {
    // empty
  }
  return [...byCode.values()].sort((a, b) => a.code.localeCompare(b.code, 'vi'));
}

function rowCl(r: CompanyRow): number {
  return round0(Number(r.cl) || 0);
}

function selectedBase(rows: CompanyRow[]): number {
  return rows.filter(r => r.selected).reduce((s, r) => s + round0(Number(r.amount) || 0), 0);
}

function selectedCl(rows: CompanyRow[]): number {
  return rows.filter(r => r.selected).reduce((s, r) => s + rowCl(r), 0);
}

function applyEqual(rows: CompanyRow[], total: number): CompanyRow[] {
  const selected = rows.filter(r => r.selected);
  if (selected.length === 0) return rows;
  const n = selected.length;
  const base = Math.floor(total / n);
  let allocated = 0;
  const amounts = new Map<string, { amount: number; ratio: number }>();
  selected.forEach((r, i) => {
    const amount = i === n - 1 ? total - allocated : base;
    if (i < n - 1) allocated += amount;
    const ratio = total > 0 ? Math.round((amount * 10000) / total) / 100 : 0;
    amounts.set(r.rowKey, { amount, ratio });
  });
  return rows.map(r => {
    if (!r.selected) return { ...r, amount: 0, ratio: 0, cl: 0 };
    const calc = amounts.get(r.rowKey);
    return calc ? { ...r, amount: calc.amount, ratio: calc.ratio, cl: 0 } : r;
  });
}

function applyRatio(rows: CompanyRow[], total: number): CompanyRow[] {
  const selected = rows.filter(r => r.selected);
  if (selected.length === 0) {
    return rows.map(r => (r.selected ? r : { ...r, amount: 0 }));
  }
  /** Tỷ lệ user nhập = % tổng tiền; không chuẩn hóa / không đẩy dư vào dòng cuối. */
  return rows.map(r => {
    if (!r.selected) return { ...r, amount: 0, cl: 0 };
    const pct = Number(r.ratio) || 0;
    const amount = round0((total * pct) / 100);
    return { ...r, amount, ratio: pct, cl: 0 };
  });
}

function resetRowsToDefault(rows: CompanyRow[]): CompanyRow[] {
  return rows.map(r => ({ ...r, selected: false, amount: 0, ratio: 0, cl: 0, costCode: r.costCode, costCodeName: r.costCodeName }));
}

function recompute(nextMethod: CompanyAllocationMethod, nextRows: CompanyRow[], total: number): CompanyRow[] {
  if (nextMethod === 'Equal') return applyEqual(nextRows, total);
  if (nextMethod === 'Ratio') return applyRatio(nextRows, total);
  return nextRows;
}

export const CompanyAllocateSlideout: React.FC<CompanyAllocateSlideoutProps> = ({
  isOpen,
  onClose,
  voucherTotal,
  voucherLines = [],
  initialMethod = 'Manual',
  initialScope = 'Common',
  initialActiveLineId,
  initialLines,
  onConfirm,
  onOpenLineDetailTab,
  testIdPrefix,
  saving = false,
  readOnly = false,
}) => {
  const dispatch = useAppDispatch();
  const multiLine = voucherLines.length > 1;
  const [loading, setLoading] = useState(false);
  const [method, setMethod] = useState<CompanyAllocationMethod>('Manual');
  const [scope, setScope] = useState<CompanyAllocationScope>('Common');
  const [activeLineId, setActiveLineId] = useState<string>('');
  const [rows, setRows] = useState<CompanyRow[]>([]);
  const [submitting, setSubmitting] = useState(false);
  const [scopeConfirmOpen, setScopeConfirmOpen] = useState(false);
  const [pendingScope, setPendingScope] = useState<CompanyAllocationScope | null>(null);
  const [byLineState, setByLineState] = useState<Record<string, LineBucket>>({});
  /** remount detail → animation khi đổi mode / chọn hạng mục */
  const [detailAnimKey, setDetailAnimKey] = useState(0);
  const [companyCatalog, setCompanyCatalog] = useState<{ code: string; name: string }[]>([]);
  const [focusedRowKey, setFocusedRowKey] = useState<string>('');
  const costCodeSearchConfig = useMemo(() => createCostCodeSearchConfig(), []);
  const companyCodeSearchConfig = useMemo(() => createCompanyCodeSearchConfig(), []);

  const lineDefaultCost = useCallback((lineId?: string | null) => {
    if (lineId) return (voucherLines.find(l => l.id === lineId)?.costCode || '').trim();
    if (voucherLines.length === 1) return (voucherLines[0].costCode || '').trim();
    return '';
  }, [voucherLines]);

  const lineDefaultCostName = useCallback((lineId?: string | null) => {
    if (lineId) return (voucherLines.find(l => l.id === lineId)?.costCodeName || '').trim();
    if (voucherLines.length === 1) return (voucherLines[0].costCodeName || '').trim();
    return '';
  }, [voucherLines]);

  const activeTotal = useMemo(() => {
    if (scope === 'ByLine' && activeLineId) {
      const line = voucherLines.find(l => l.id === activeLineId);
      return round0(line?.amount ?? 0);
    }
    return round0(voucherTotal);
  }, [scope, activeLineId, voucherLines, voucherTotal]);

  useEffect(() => {
    if (!isOpen) return;
    let cancelled = false;
    setLoading(true);
    const initMethod = normalizeMethod(initialMethod);
    const focusLineId = (initialActiveLineId ?? '').trim();
    const focusExists = !!focusLineId && voucherLines.some(l => l.id === focusLineId);
    const hasSavedByLine = (initialLines ?? []).some(l => !!(l as { cashVoucherLineId?: string | null }).cashVoucherLineId);
    const hasSavedCommon = (initialLines ?? []).some(l =>
      !(l as { cashVoucherLineId?: string | null }).cashVoucherLineId && !l.isRoundingDiff);
    const initScope = focusExists
      ? 'ByLine'
      : !multiLine
        ? 'Common'
        : hasSavedByLine
          ? 'ByLine'
          : hasSavedCommon
            ? 'Common'
            : 'ByLine';
    setMethod(initMethod);
    setScope(initScope);
    setScopeConfirmOpen(false);
    setPendingScope(null);
    setDetailAnimKey(k => k + 1);

    void (async () => {
      try {
        const companies = await fetchActiveCompanies();
        if (cancelled) return;
        setCompanyCatalog(companies);

        const defaultCost = (lineId?: string | null) => {
          if (lineId) {
            return (voucherLines.find(l => l.id === lineId)?.costCode || '').trim();
          }
          if (voucherLines.length === 1) return (voucherLines[0].costCode || '').trim();
          return '';
        };
        const defaultCostName = (lineId?: string | null) => {
          if (lineId) return (voucherLines.find(l => l.id === lineId)?.costCodeName || '').trim();
          if (voucherLines.length === 1) return (voucherLines[0].costCodeName || '').trim();
          return '';
        };

        const seedRows = (lineFilter?: string | null): CompanyRow[] => {
          const fillCost = defaultCost(lineFilter);
          const fillName = defaultCostName(lineFilter);
          const onlyLineId = voucherLines.length === 1 ? voucherLines[0].id : '';
          const matchesLine = (l: CashVoucherCompanyAllocationDto) => {
            const lineId = (l.cashVoucherLineId ?? '').trim();
            if (lineFilter) return lineId === lineFilter || (!lineId && !multiLine);
            if (!lineId) return initScope === 'Common' || !multiLine;
            return !!onlyLineId && lineId === onlyLineId;
          };
          const pairKey = (co: string, cost?: string | null) =>
            `${co.toUpperCase()}::${(cost || '').trim().toUpperCase()}`;
          const clByPair = new Map<string, number>();
          for (const l of initialLines ?? []) {
            if (!l.isRoundingDiff || isSystemCode(l.targetCompanyCode) || !matchesLine(l)) continue;
            const key = pairKey(l.targetCompanyCode, lineCostCode(l));
            clByPair.set(key, (clByPair.get(key) ?? 0) + (Number(l.amount) || 0));
          }
          const filtered = (initialLines ?? []).filter(l =>
            !isSystemCode(l.targetCompanyCode) && !l.isRoundingDiff && matchesLine(l));
          const used = new Set<string>();
          const clOf = (co: string, cost?: string | null) => clByPair.get(pairKey(co, cost)) ?? 0;
          let next: CompanyRow[] = companies.map(c => {
            const prev = filtered.find(l => l.targetCompanyCode.toUpperCase() === c.code.toUpperCase());
            if (prev) used.add(pairKey(prev.targetCompanyCode, lineCostCode(prev)));
            const cost = prev ? (lineCostCode(prev) || fillCost) : fillCost;
            return {
              rowKey: newRowKey(),
              code: c.code,
              name: prev?.targetCompanyName || c.name,
              costCode: cost,
              costCodeName: prev ? '' : fillName,
              selected: !!prev,
              amount: prev ? Number(prev.amount) || 0 : 0,
              ratio: prev ? Number(prev.ratio) || 0 : 0,
              cl: prev ? clOf(prev.targetCompanyCode, lineCostCode(prev) || cost) : 0,
            };
          });
          for (const line of filtered) {
            const key = pairKey(line.targetCompanyCode, lineCostCode(line));
            if (used.has(key) || isSystemCode(line.targetCompanyCode)) continue;
            used.add(key);
            next.push({
              rowKey: newRowKey(),
              code: line.targetCompanyCode,
              name: line.targetCompanyName || line.targetCompanyCode,
              costCode: lineCostCode(line) || fillCost,
              costCodeName: fillName,
              selected: true,
              amount: Number(line.amount) || 0,
              ratio: Number(line.ratio) || 0,
              cl: clOf(line.targetCompanyCode, lineCostCode(line)),
            });
          }
          return next;
        };

        if (initScope === 'ByLine' && multiLine) {
          const firstId = focusExists ? focusLineId : (voucherLines[0]?.id ?? '');
          setActiveLineId(firstId);
          const state: Record<string, LineBucket> = {};
          for (const vl of voucherLines) {
            const allocs = (initialLines ?? []).filter(
              l => !l.isRoundingDiff && (l.cashVoucherLineId ?? null) === vl.id,
            );
            const lineMethod = normalizeMethod(allocs[0]?.method ?? initMethod);
            let next = seedRows(vl.id);
            const total = round0(vl.amount);
            const hasSaved = (initialLines ?? []).some(
              l => !l.isRoundingDiff && (l.cashVoucherLineId ?? null) === vl.id,
            );
            if (!hasSaved && lineMethod === 'Equal' && next.some(x => x.selected)) next = applyEqual(next, total);
            else if (!hasSaved && lineMethod === 'Ratio' && next.some(x => x.selected)) next = applyRatio(next, total);
            state[vl.id] = { rows: next, method: lineMethod, clAmount: 0, clCode: '' };
          }
          setByLineState(state);
          const active = state[firstId];
          setRows(active?.rows ?? seedRows(firstId));
          setMethod(active?.method ?? initMethod);
        } else {
          const onlyId = voucherLines.length === 1 ? voucherLines[0].id : null;
          const seedFilter = initScope === 'ByLine' || hasSavedByLine ? onlyId : null;
          let next = seedRows(seedFilter);
          const hasSaved = (initialLines ?? []).some(l => !l.isRoundingDiff);
          if (!hasSaved && initMethod === 'Equal' && next.some(r => r.selected)) {
            next = applyEqual(next, round0(voucherTotal));
          } else if (!hasSaved && initMethod === 'Ratio' && next.some(r => r.selected)) {
            next = applyRatio(next, round0(voucherTotal));
          }
          setRows(next);
          setByLineState({});
          setActiveLineId(onlyId && (initScope === 'ByLine' || hasSavedByLine) ? onlyId : '');
        }
      } catch (e: unknown) {
        if (!cancelled) {
          dispatchAppToast(dispatch, {
            message: getApiErrorMessage(e, 'Không tải được danh sách đơn vị cơ sở.'),
            type: 'error',
          });
        }
      } finally {
        if (!cancelled) setLoading(false);
      }
    })();

    return () => { cancelled = true; };
  }, [isOpen, initialMethod, initialScope, initialActiveLineId, initialLines, voucherTotal, multiLine, voucherLines, dispatch]);

  const selectedTotal = useMemo(() => selectedBase(rows) + selectedCl(rows), [rows]);
  const baseAlloc = useMemo(() => selectedBase(rows), [rows]);
  const clAlloc = useMemo(() => selectedCl(rows), [rows]);

  const totalRounded = activeTotal;
  const grandAlloc = selectedTotal;
  const diff = grandAlloc - totalRounded;
  const needsCl = Math.abs(baseAlloc - totalRounded) !== 0 || clAlloc !== 0;

  const persistActiveByLine = useCallback((
    nextRows: CompanyRow[],
    nextMethod: CompanyAllocationMethod,
  ) => {
    if (scope !== 'ByLine' || !activeLineId) return;
    setByLineState(prev => ({
      ...prev,
      [activeLineId]: { rows: nextRows, method: nextMethod, clAmount: 0, clCode: '' },
    }));
  }, [scope, activeLineId]);

  const handleMethodChangeRequest = (next: CompanyAllocationMethod) => {
    if (next === method || readOnly) return;
    setMethod(next);
    let kept = rows.map(r => ({ ...r }));
    if (next === 'Ratio' && totalRounded > 0) {
      const selected = kept.filter(r => r.selected);
      const hasRatio = selected.some(r => (Number(r.ratio) || 0) > 0);
      if (!hasRatio) {
        kept = kept.map(r => r.selected
          ? { ...r, ratio: Math.round(((Number(r.amount) || 0) * 10000) / totalRounded) / 100 }
          : r);
      }
    }
    const recomputed = recompute(next, kept, totalRounded);
    setRows(recomputed);
    persistActiveByLine(recomputed, next);
  };

  const handleScopeChangeRequest = (next: CompanyAllocationScope) => {
    if (next === scope || readOnly) return;
    setPendingScope(next);
    setScopeConfirmOpen(true);
  };

  const confirmScopeChange = () => {
    if (!pendingScope) {
      setScopeConfirmOpen(false);
      return;
    }
    const next = pendingScope;
    setScope(next);
    setMethod('Manual');
    setScopeConfirmOpen(false);
    setPendingScope(null);
    const reset = resetRowsToDefault(rows);
    setRows(reset);
    setDetailAnimKey(k => k + 1);
    if (next === 'ByLine' && multiLine) {
      const firstId = voucherLines[0]?.id ?? '';
      setActiveLineId(firstId);
      const state: Record<string, LineBucket> = {};
      for (const vl of voucherLines) {
        state[vl.id] = {
          rows: resetRowsToDefault(rows.map(r => ({ ...r }))),
          method: 'Manual',
          clAmount: 0,
          clCode: '',
        };
      }
      setByLineState(state);
    } else {
      setByLineState({});
      setActiveLineId('');
    }
  };

  const cancelScopeChange = () => {
    setScopeConfirmOpen(false);
    setPendingScope(null);
  };

  const switchActiveLine = (lineId: string) => {
    if (lineId === activeLineId) return;
    persistActiveByLine(rows, method);
    setActiveLineId(lineId);
    setDetailAnimKey(k => k + 1);
    const st = byLineState[lineId];
    if (st) {
      setRows(st.rows);
      setMethod(st.method);
    } else {
      setRows(resetRowsToDefault(rows));
      setMethod('Manual');
    }
  };

  const handleAddRow = () => {
    if (readOnly) return;
    const lineId = scope === 'ByLine' ? activeLineId : (voucherLines.length === 1 ? voucherLines[0].id : null);
    const nextRow: CompanyRow = {
      rowKey: newRowKey(),
      code: '',
      name: '',
      costCode: lineDefaultCost(lineId),
      costCodeName: lineDefaultCostName(lineId),
      selected: true,
      amount: 0,
      ratio: 0,
      cl: 0,
    };
    setRows(prev => {
      const next = [...prev, nextRow];
      persistActiveByLine(next, method);
      return next;
    });
    setFocusedRowKey(nextRow.rowKey);
  };

  const handleDuplicateRow = () => {
    if (readOnly || rows.length === 0) return;
    const src = rows.find(r => r.rowKey === focusedRowKey) ?? rows.find(r => r.selected) ?? rows[rows.length - 1];
    const nextRow: CompanyRow = {
      ...src,
      rowKey: newRowKey(),
      selected: true,
    };
    setRows(prev => {
      const next = [...prev, nextRow];
      persistActiveByLine(next, method);
      return next;
    });
    setFocusedRowKey(nextRow.rowKey);
  };

  const handleRemoveRow = (rowKey: string) => {
    if (readOnly) return;
    setRows(prev => {
      const next = prev.filter(r => r.rowKey !== rowKey);
      persistActiveByLine(next, method);
      return next;
    });
    if (focusedRowKey === rowKey) setFocusedRowKey('');
  };

  const handleSelectAll = (checked: boolean) => {
    setRows(prev => {
      const next = prev.map(r => ({
        ...r,
        selected: checked,
        amount: checked ? r.amount : 0,
        ratio: checked ? r.ratio : 0,
        cl: checked ? r.cl : 0,
      }));
      const recomputed = recompute(method, next, totalRounded);
      persistActiveByLine(recomputed, method);
      return recomputed;
    });
  };

  const buildPayload = (): CompanyAllocateConfirmPayload => {
    const buildLinesFrom = (r: CompanyRow[], lineId: string | null) => {
      const selected = r.filter(x => x.selected && x.code.trim() && !isSystemCode(x.code));
      const lineKey = lineId
        ? (voucherLines.find(l => l.id === lineId)?.rowOrderKey ?? 0)
        : 0;
      const out: SaveCashVoucherCompanyAllocationDto['lines'] = [];
      let sort = 0;
      for (const row of selected) {
        out.push({
          targetCompanyCode: row.code,
          targetCompanyName: row.name,
          amount: round0(Number(row.amount) || 0),
          ratio: Number(row.ratio) || 0,
          sortOrder: sort++,
          cashVoucherLineId: lineId,
          isRoundingDiff: false,
          costCode: row.costCode.trim() || null,
          rowOrderKey: lineKey,
        });
        const cl = rowCl(row);
        if (cl !== 0) {
          out.push({
            targetCompanyCode: row.code,
            targetCompanyName: row.name,
            amount: cl,
            ratio: 0,
            sortOrder: sort++,
            cashVoucherLineId: lineId,
            isRoundingDiff: true,
            costCode: row.costCode.trim() || null,
            rowOrderKey: lineKey,
          });
        }
      }
      return out;
    };

    if (scope === 'ByLine') {
      const snapshot: Record<string, LineBucket> = {
        ...byLineState,
        [activeLineId]: { rows, method, clAmount: 0, clCode: '' },
      };
      const all: CompanyAllocateConfirmPayload['lines'] = [];
      for (const vl of voucherLines) {
        const st = snapshot[vl.id];
        all.push(...buildLinesFrom(st?.rows ?? [], vl.id));
      }
      // BE NormalizeBucket 1 method toàn phiếu — Manual giữ số tiền đã tính per-line
      return { method: 'Manual', scope: 'ByLine', lines: all };
    }

    return {
      method,
      scope: 'Common',
      lines: buildLinesFrom(rows, null),
    };
  };

  const handleConfirm = async () => {
    const payload = buildPayload();
    if (payload.lines.length === 0) {
      dispatchAppToast(dispatch, {
        message: 'Chọn ít nhất một đơn vị cơ sở để phân bổ.',
        type: 'warning',
      });
      return;
    }
    if (totalRounded <= 0 && scope === 'Common') {
      dispatchAppToast(dispatch, {
        message: 'Tổng tiền phiếu chưa hợp lệ — không thể phân bổ.',
        type: 'error',
      });
      return;
    }

    if (scope === 'Common') {
      const sum = payload.lines.reduce((s, l) => s + (Number(l.amount) || 0), 0);
      if (sum !== round0(voucherTotal)) {
        dispatchAppToast(dispatch, {
          message: `Còn chênh lệch ${formatMoneyVnd(sum - round0(voucherTotal))} — nhập CL (±) trên dòng để cân bằng.`,
          type: 'error',
        });
        return;
      }
      if (method === 'Ratio') {
        const selected = rows.filter(r => r.selected);
        const hasRatio = selected.some(r => (Number(r.ratio) || 0) > 0);
        if (!hasRatio) {
          dispatchAppToast(dispatch, {
            message: 'Nhập tỷ lệ lớn hơn 0 cho các đơn vị đã chọn.',
            type: 'error',
          });
          return;
        }
      }
    } else {
      const snapshot: Record<string, LineBucket> = {
        ...byLineState,
        [activeLineId]: { rows, method, clAmount: 0, clCode: '' },
      };
      for (const vl of voucherLines) {
        const lineLines = payload.lines.filter(l => l.cashVoucherLineId === vl.id);
        if (lineLines.length === 0) continue;
        const sum = lineLines.reduce((s, l) => s + (Number(l.amount) || 0), 0);
        if (sum !== round0(vl.amount)) {
          dispatchAppToast(dispatch, {
            message: `Dòng ${vl.label}: còn chênh lệch ${formatMoneyVnd(sum - round0(vl.amount))} — nhập CL (±) để cân bằng.`,
            type: 'error',
          });
          return;
        }
        const st = snapshot[vl.id];
        if (st?.method === 'Ratio') {
          const selected = st.rows.filter(r => r.selected);
          const hasRatio = selected.some(r => (Number(r.ratio) || 0) > 0);
          if (!hasRatio) {
            dispatchAppToast(dispatch, {
              message: `Dòng ${vl.label}: nhập tỷ lệ lớn hơn 0.`,
              type: 'error',
            });
            return;
          }
        }
      }
    }

    setSubmitting(true);
    try {
      await onConfirm(payload);
      if (scope === 'ByLine' && onOpenLineDetailTab) {
        onOpenLineDetailTab(payload);
      }
      onClose();
    } catch (e: unknown) {
      dispatchAppToast(dispatch, {
        message: getApiErrorMessage(e, 'Không lưu được phân bổ.'),
        type: 'error',
      });
    } finally {
      setSubmitting(false);
    }
  };

  const allSelected = rows.length > 0 && rows.every(r => r.selected);
  const busy = loading || saving || submitting;

  const lineStats = useMemo(() => {
    if (scope !== 'ByLine') return [];
    const snapshot: Record<string, LineBucket> = {
      ...byLineState,
      ...(activeLineId ? { [activeLineId]: { rows, method, clAmount: 0, clCode: '' } } : {}),
    };
    return voucherLines.map(vl => {
      const st = snapshot[vl.id];
      const companyRows = st?.rows ?? [];
      const selected = companyRows.filter(r => r.selected);
      const unitCount = selected.length;
      const sumAmt = selected.reduce((s, r) => s + round0(Number(r.amount) || 0) + rowCl(r), 0);
      const lineTotal = round0(vl.amount);
      const variance = sumAmt - lineTotal;
      return {
        id: vl.id,
        label: vl.label,
        lineTotal,
        unitCount,
        sumAmt,
        variance,
        method: st?.method ?? 'Manual',
        companyCodes: selected.map(r => r.code),
      };
    });
  }, [scope, byLineState, activeLineId, rows, method, voucherLines]);

  const applyCompanyAt = (idx: number, item: CompanyCodeLookupItem) => {
    const code = (item.code || '').trim();
    if (!code || isSystemCode(code)) {
      dispatchAppToast(dispatch, { message: 'Mã đơn vị không hợp lệ.', type: 'warning' });
      return;
    }
    setRows(prev => {
      const next = prev.map((r, i) => (i === idx
        ? {
            ...r,
            code,
            name: (item.name || item.shortName || code).trim(),
            selected: true,
          }
        : r));
      persistActiveByLine(next, method);
      return next;
    });
  };

  const showDetail = !loading && (scope === 'Common' || !!activeLineId);
  const detailTitle = scope === 'ByLine'
    ? (voucherLines.find(l => l.id === activeLineId)?.label ?? 'Đơn vị cơ sở')
    : 'Phân bổ chung';

  const footer = (
    <div className={styles.allocFooter}>
      {!readOnly && (
        <div className={styles.allocFooterLeft}>
          <Button
            variant="secondary"
            onClick={handleAddRow}
            disabled={busy}
            data-testid={`${testIdPrefix}-company-allocate-add`}
          >
            Thêm dòng
          </Button>
          <Button
            variant="secondary"
            onClick={handleDuplicateRow}
            disabled={busy || rows.length === 0}
            data-testid={`${testIdPrefix}-company-allocate-duplicate`}
          >
            Sao chép dòng
          </Button>
        </div>
      )}
      <div className={formStyles.modalActions}>
        <Button variant="secondary" onClick={onClose} data-testid={`${testIdPrefix}-company-allocate-cancel`}>
          {readOnly ? 'Đóng' : 'Hủy'}
        </Button>
        {!readOnly && (
          <Button
            variant="primary"
            onClick={() => void handleConfirm()}
            disabled={busy || rows.length === 0 || (scope === 'Common' && diff !== 0)}
            data-testid={`${testIdPrefix}-company-allocate-confirm`}
          >
            {busy ? 'Đang lưu…' : 'Xác nhận phân bổ'}
          </Button>
        )}
      </div>
    </div>
  );

  const renderCompanyGrid = () => (
    <div className={styles.detailGridWrap}>
      <table className={styles.gridTable} data-testid={`${testIdPrefix}-company-allocate-detail-grid`}>
        <thead>
          <tr>
            <th className={styles.colCheck} scope="col">
              {!readOnly && (
                <span className={styles.cellCheck}>
                  <input
                    type="checkbox"
                    checked={allSelected}
                    data-testid={`${testIdPrefix}-company-allocate-select-all`}
                    onChange={e => handleSelectAll(e.target.checked)}
                    title="Chọn tất cả"
                    aria-label="Chọn tất cả đơn vị"
                  />
                </span>
              )}
            </th>
            <th className={styles.colCode} scope="col">Mã ĐVCS</th>
            <th className={styles.colName} scope="col">Tên đơn vị</th>
            <th className={styles.colCode} scope="col">Mã CP</th>
            {method === 'Ratio' && <th className={styles.colNum} scope="col">Tỷ lệ</th>}
            <th className={styles.colAmount} scope="col">Số tiền</th>
            <th
              className={`${styles.colCl} ${needsCl ? styles.colClRequired : ''}`}
              scope="col"
              title="Chênh lệch làm tròn — nhập số dương hoặc âm"
            >
              CL{needsCl ? ' *' : ''}
            </th>
            {!readOnly && <th className={styles.colDel} scope="col" />}
          </tr>
        </thead>
        <tbody>
          {rows.map((row, idx) => (
            <tr
              key={row.rowKey}
              className={focusedRowKey === row.rowKey ? styles.rowFocused : undefined}
              data-testid={`${testIdPrefix}-company-allocate-row-${idx}`}
              onClick={() => setFocusedRowKey(row.rowKey)}
            >
              <td className={styles.colCheck}>
                <span className={styles.cellCheck}>
                  <input
                    type="checkbox"
                    checked={row.selected}
                    disabled={readOnly}
                    data-testid={`${testIdPrefix}-company-allocate-select-${idx}`}
                    aria-label={`Chọn ${row.code}`}
                    onChange={e => {
                      const checked = e.target.checked;
                      const lineId = scope === 'ByLine' ? activeLineId : (voucherLines.length === 1 ? voucherLines[0].id : null);
                      const fillCost = lineDefaultCost(lineId);
                      const fillName = lineDefaultCostName(lineId);
                      setRows(prev => {
                        const next = prev.map((r, i) => (i === idx
                          ? {
                              ...r,
                              selected: checked,
                              amount: checked ? r.amount : 0,
                              ratio: checked ? r.ratio : 0,
                              cl: checked ? r.cl : 0,
                              costCode: checked && !r.costCode && fillCost ? fillCost : r.costCode,
                              costCodeName: checked && !r.costCode && fillName ? fillName : r.costCodeName,
                            }
                          : r));
                        const recomputed = recompute(method, next, totalRounded);
                        persistActiveByLine(recomputed, method);
                        return recomputed;
                      });
                    }}
                  />
                </span>
              </td>
              <td className={styles.colCompany} onClick={e => e.stopPropagation()}>
                <SearchInput
                  config={companyCodeSearchConfig}
                  value={row.code}
                  primaryDisplay={formatAccountDisplay(row.code, row.name)}
                  disabled={readOnly}
                  placeholder="Mã ĐVCS..."
                  showSecondaryInput={false}
                  showLabel={false}
                  onChange={(c: CompanyCodeLookupItem) => applyCompanyAt(idx, c)}
                  onClear={() => {
                    setRows(prev => {
                      const next = prev.map((r, i) => (i === idx
                        ? { ...r, code: '', name: '', selected: false, amount: 0, ratio: 0 }
                        : r));
                      persistActiveByLine(next, method);
                      return next;
                    });
                  }}
                  renderDropdownFooter={(ctx: { search?: string; term?: string; close?: () => void }) => {
                    const term = (ctx.search ?? ctx.term ?? '').trim().toUpperCase();
                    if (!term || isSystemCode(term)) return null;
                    const known = companyCatalog.some(c => c.code.toUpperCase() === term);
                    if (known) return null;
                    return (
                      <button
                        type="button"
                        className={styles.useTypedCode}
                        data-testid={`${testIdPrefix}-company-allocate-use-typed-${idx}`}
                        onMouseDown={e => e.preventDefault()}
                        onClick={() => {
                          applyCompanyAt(idx, { code: term, name: term });
                          ctx.close?.();
                        }}
                      >
                        Dùng mã {term}
                      </button>
                    );
                  }}
                />
              </td>
              <td className={styles.colName}>{row.name || '—'}</td>
              <td className={styles.colCost} onClick={e => e.stopPropagation()}>
                <SearchInput
                  config={costCodeSearchConfig}
                  value={row.costCode}
                  primaryDisplay={formatAccountDisplay(row.costCode, row.costCodeName)}
                  disabled={readOnly || !row.selected}
                  placeholder="Mã chi phí..."
                  showSecondaryInput={false}
                  onChange={(c: CostCodeLookupItem) => {
                    setRows(prev => {
                      const next = prev.map((r, i) => (i === idx
                        ? { ...r, costCode: c.code, costCodeName: c.name || '' }
                        : r));
                      persistActiveByLine(next, method);
                      return next;
                    });
                  }}
                  onClear={() => {
                    setRows(prev => {
                      const next = prev.map((r, i) => (i === idx
                        ? { ...r, costCode: '', costCodeName: '' }
                        : r));
                      persistActiveByLine(next, method);
                      return next;
                    });
                  }}
                />
              </td>
              {method === 'Ratio' && (
                <td className={styles.colNum}>
                  <MoneyInput
                    value={row.ratio}
                    disabled={readOnly || !row.selected}
                    data-testid={`${testIdPrefix}-company-allocate-ratio-${idx}`}
                    onChange={ratio => {
                      setRows(prev => {
                        const next = prev.map((r, i) => (i === idx ? { ...r, ratio } : r));
                        const recomputed = recompute(method, next, totalRounded);
                        persistActiveByLine(recomputed, method);
                        return recomputed;
                      });
                    }}
                  />
                </td>
              )}
              <td className={styles.colAmount}>
                <MoneyInput
                  value={row.amount}
                  disabled={readOnly || !row.selected || method !== 'Manual'}
                  data-testid={`${testIdPrefix}-company-allocate-amount-${idx}`}
                  onChange={amount => {
                    setRows(prev => {
                      const next = prev.map((r, i) => (i === idx ? { ...r, amount } : r));
                      persistActiveByLine(next, method);
                      return next;
                    });
                  }}
                />
              </td>
              <td className={styles.colCl} onClick={e => e.stopPropagation()}>
                <IntegerInput
                  value={row.cl}
                  min={-999_999_999_999}
                  max={999_999_999_999}
                  disabled={readOnly || !row.selected}
                  data-testid={`${testIdPrefix}-company-allocate-cl-${idx}`}
                  onChange={cl => {
                    setRows(prev => {
                      const next = prev.map((r, i) => (i === idx ? { ...r, cl } : r));
                      persistActiveByLine(next, method);
                      return next;
                    });
                  }}
                />
              </td>
              {!readOnly && (
                <td className={styles.colDel} onClick={e => e.stopPropagation()}>
                  <button
                    type="button"
                    className={styles.btnRemove}
                    title="Xóa dòng"
                    data-testid={`${testIdPrefix}-company-allocate-remove-${idx}`}
                    onClick={() => handleRemoveRow(row.rowKey)}
                  >
                    <i className="fas fa-trash-alt" aria-hidden="true" />
                  </button>
                </td>
              )}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );

  return (
    <>
    <Slideout
      isOpen={isOpen}
      onClose={onClose}
      title="Phân bổ theo đơn vị / mã chi phí"
      width="min(1100px, 96vw)"
      customFooter={footer}
      data-testid={`${testIdPrefix}-company-allocate-slideout`}
    >
      <div className={styles.root}>
        {loading ? (
          <p className={formStyles.loading} data-testid={`${testIdPrefix}-company-allocate-loading`}>
            Đang tải…
          </p>
        ) : (
          <>
            <div className={styles.scopeBar}>
              {multiLine && (
                <div className={styles.field}>
                  <label className={formStyles.label} htmlFor={`${testIdPrefix}-company-allocate-scope`}>
                    Phạm vi
                  </label>
                  <select
                    id={`${testIdPrefix}-company-allocate-scope`}
                    className={styles.select}
                    data-testid={`${testIdPrefix}-company-allocate-scope`}
                    value={scope}
                    disabled={readOnly}
                    onChange={e => handleScopeChangeRequest(e.target.value as CompanyAllocationScope)}
                  >
                    <option value="Common">1 — Phân bổ chung</option>
                    <option value="ByLine">2 — Phân bổ theo dòng</option>
                  </select>
                </div>
              )}
              {!multiLine && (
                <div className={styles.field}>
                  <span className={formStyles.label}>Phạm vi</span>
                  <span className={styles.summaryValue}>Phân bổ chung</span>
                </div>
              )}
            </div>

            {/* ByLine: lưới hạng mục chi phí (max 4 dòng visible) */}
            {scope === 'ByLine' && multiLine && (
              <section data-testid={`${testIdPrefix}-company-allocate-lines`}>
                <h4 className={formStyles.sectionTitle}>Hạng mục chi phí</h4>
                <p className={styles.hint}>
                  Chọn một dòng để phân bổ đơn vị cơ sở bên dưới. Mỗi dòng có thể chọn hình thức phân bổ riêng.
                </p>
                <div
                  className={styles.masterScroll}
                  data-testid={`${testIdPrefix}-company-allocate-line-scroll`}
                >
                  <table className={styles.gridTable} data-testid={`${testIdPrefix}-company-allocate-line-grid`}>
                    <thead>
                      <tr>
                        <th className={styles.colCheck} scope="col" />
                        <th scope="col">Hạng mục</th>
                        <th className={styles.colAmount} scope="col">Tiền dòng</th>
                        <th className={styles.colMethod} scope="col">Hình thức</th>
                        <th className={styles.colNum} scope="col">Số ĐVCS</th>
                        <th className={styles.colAmount} scope="col">Tổng phân bổ</th>
                        <th className={styles.colAmount} scope="col">Chênh lệch</th>
                        <th className={styles.colCompanies} scope="col">ĐVCS đã chọn</th>
                      </tr>
                    </thead>
                    <tbody>
                      {lineStats.map((m, idx) => {
                        const active = m.id === activeLineId;
                        const ok = m.variance === 0 && m.unitCount > 0;
                        const empty = m.unitCount === 0;
                        return (
                          <tr
                            key={m.id}
                            className={`${styles.masterRow} ${active ? styles.masterRowActive : ''}`}
                            data-testid={`${testIdPrefix}-company-allocate-line-row-${idx}`}
                            onClick={() => switchActiveLine(m.id)}
                          >
                            <td className={styles.colCheck}>
                              <span className={styles.cellCheck}>
                                <input
                                  type="radio"
                                  name={`${testIdPrefix}-alloc-line`}
                                  checked={active}
                                  readOnly
                                  data-testid={`${testIdPrefix}-company-allocate-line-radio-${idx}`}
                                  aria-label={`Chọn hạng mục ${m.label}`}
                                />
                              </span>
                            </td>
                            <td><strong>{m.label}</strong></td>
                            <td className={styles.colAmount}>{formatMoneyVnd(m.lineTotal)}</td>
                            <td className={styles.colMethod}>{methodLabel(m.method)}</td>
                            <td className={styles.colNum}>{m.unitCount}</td>
                            <td className={styles.colAmount}>{formatMoneyVnd(m.sumAmt)}</td>
                            <td
                              className={`${styles.colAmount} ${empty ? styles.diffEmpty : ok ? styles.diffOk : styles.diffBad}`}
                              data-testid={`${testIdPrefix}-company-allocate-line-diff-${idx}`}
                            >
                              {empty ? '—' : formatMoneyVnd(m.variance)}
                              {!empty && ok ? ' ✓' : ''}
                            </td>
                            <td className={styles.colCompanies}>
                              {m.companyCodes.length > 0 ? m.companyCodes.join(', ') : '—'}
                            </td>
                          </tr>
                        );
                      })}
                    </tbody>
                  </table>
                </div>
              </section>
            )}

            {/* Detail panel — dưới dòng / form phân bổ; animation khi show / đổi dòng */}
            {showDetail && (
              <section
                key={`${scope}-${activeLineId || 'common'}-${detailAnimKey}`}
                className={styles.detailPanel}
                data-testid={`${testIdPrefix}-company-allocate-detail`}
              >
                <h4 className={formStyles.sectionTitle}>{detailTitle}</h4>

                <div className={styles.summaryBlock} data-testid={`${testIdPrefix}-company-allocate-summary`}>
                  {/* 1 line: Hình thức · Số tiền · Đã phân bổ · Chênh lệch */}
                  <div className={styles.summaryLine}>
                    <div className={styles.field}>
                      <label className={formStyles.label} htmlFor={`${testIdPrefix}-company-allocate-method`}>
                        Hình thức phân bổ
                      </label>
                      <select
                        id={`${testIdPrefix}-company-allocate-method`}
                        className={styles.select}
                        data-testid={`${testIdPrefix}-company-allocate-method`}
                        value={method}
                        disabled={readOnly}
                        onChange={e => handleMethodChangeRequest(e.target.value as CompanyAllocationMethod)}
                      >
                        {METHOD_OPTIONS.map(o => (
                          <option key={o.value} value={o.value}>{o.label}</option>
                        ))}
                      </select>
                    </div>
                    <div className={styles.field}>
                      <span className={formStyles.label}>Số tiền</span>
                      <span
                        className={styles.summaryValue}
                        data-testid={`${testIdPrefix}-company-allocate-amount-total`}
                      >
                        {formatMoneyVnd(totalRounded)}
                      </span>
                    </div>
                    <div className={styles.field}>
                      <span className={formStyles.label}>Đã phân bổ</span>
                      <span
                        className={styles.summaryValue}
                        data-testid={`${testIdPrefix}-company-allocate-sum`}
                      >
                        {formatMoneyVnd(grandAlloc)}
                      </span>
                    </div>
                    <div className={styles.field}>
                      <span className={formStyles.label}>Chênh lệch</span>
                      <span
                        className={`${styles.summaryValue} ${
                          diff !== 0 ? styles.diffBad : styles.diffOk
                        }`}
                        data-testid={`${testIdPrefix}-company-allocate-diff`}
                      >
                        {formatMoneyVnd(diff)}
                      </span>
                    </div>
                  </div>
                </div>

                {diff !== 0 && (
                  <p
                    className={styles.clGuide}
                    data-testid={`${testIdPrefix}-company-allocate-cl-guide`}
                    role="status"
                  >
                    <strong>Bắt buộc nhập CL.</strong>
                    {' '}
                    Còn chênh lệch {formatMoneyVnd(diff)}
                    {Math.abs(diff) === 1 ? ' (làm tròn 1đ)' : ''}.
                    Nhập CL (±) trên dòng để bù — tổng số tiền + CL phải khớp {formatMoneyVnd(totalRounded)}.
                  </p>
                )}

                {renderCompanyGrid()}
              </section>
            )}
          </>
        )}
      </div>
    </Slideout>

    <Modal
      isOpen={scopeConfirmOpen}
      onClose={cancelScopeChange}
      title="Xác nhận đổi phạm vi phân bổ"
      data-testid={`${testIdPrefix}-company-allocate-scope-confirm`}
    >
      <p>
        Đổi phạm vi phân bổ sẽ xóa giá trị hiện tại. Tiếp tục?
      </p>
      <div className={formStyles.modalActions}>
        <Button
          variant="secondary"
          onClick={cancelScopeChange}
          data-testid={`${testIdPrefix}-company-allocate-scope-confirm-cancel`}
        >
          Hủy
        </Button>
        <Button
          variant="primary"
          onClick={confirmScopeChange}
          data-testid={`${testIdPrefix}-company-allocate-scope-confirm-ok`}
        >
          Xác nhận
        </Button>
      </div>
    </Modal>
    </>
  );
};
